import{_ as l,o,c as r,ah as n}from"./chunks/framework.DjU4PSOm.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["philosophy/Ethics"],"date":"2026-10-08T00:00:00.000Z"},"headers":[{"level":2,"title":"이 노트에 대하여","slug":"이-노트에-대하여","link":"#이-노트에-대하여","children":[]},{"level":2,"title":"1. 강의의 중심 물음 (슬라이드 12·19쪽 흐름)","slug":"_1-강의의-중심-물음-슬라이드-12·19쪽-흐름","link":"#_1-강의의-중심-물음-슬라이드-12·19쪽-흐름","children":[]},{"level":2,"title":"2. 보편성의 역사적 의미 (슬라이드 15쪽 내용의 확장)","slug":"_2-보편성의-역사적-의미-슬라이드-15쪽-내용의-확장","link":"#_2-보편성의-역사적-의미-슬라이드-15쪽-내용의-확장","children":[]},{"level":2,"title":"3. 보편법칙의 정식 (슬라이드 19쪽)","slug":"_3-보편법칙의-정식-슬라이드-19쪽","link":"#_3-보편법칙의-정식-슬라이드-19쪽","children":[]},{"level":2,"title":"4. 자연법칙의 정식 (슬라이드 20쪽)","slug":"_4-자연법칙의-정식-슬라이드-20쪽","link":"#_4-자연법칙의-정식-슬라이드-20쪽","children":[]},{"level":2,"title":"5. 보편화 검사의 실제 절차 (슬라이드 22쪽) + 완전/불완전 의무 (슬라이드 17·21쪽)","slug":"_5-보편화-검사의-실제-절차-슬라이드-22쪽-완전-불완전-의무-슬라이드-17·21쪽","link":"#_5-보편화-검사의-실제-절차-슬라이드-22쪽-완전-불완전-의무-슬라이드-17·21쪽","children":[]},{"level":2,"title":"6. 현대적 적용 (슬라이드 23쪽)","slug":"_6-현대적-적용-슬라이드-23쪽","link":"#_6-현대적-적용-슬라이드-23쪽","children":[]},{"level":2,"title":"7. 철학적 의의 (슬라이드 24쪽)","slug":"_7-철학적-의의-슬라이드-24쪽","link":"#_7-철학적-의의-슬라이드-24쪽","children":[]},{"level":2,"title":"8. 강점과 한계 (슬라이드 25~26쪽)","slug":"_8-강점과-한계-슬라이드-25-26쪽","link":"#_8-강점과-한계-슬라이드-25-26쪽","children":[]},{"level":2,"title":"9. 한 문장 정리 (슬라이드 29쪽)","slug":"_9-한-문장-정리-슬라이드-29쪽","link":"#_9-한-문장-정리-슬라이드-29쪽","children":[]},{"level":2,"title":"슬라이드 중 요약에 직접 나오지 않은 부분","slug":"슬라이드-중-요약에-직접-나오지-않은-부분","link":"#슬라이드-중-요약에-직접-나오지-않은-부분","children":[]}],"relativePath":"philosophy/Ethics/11. 정언명령의 보편화 검사와 칸트 윤리의 평가(5주차 온라인).md","filePath":"philosophy/Ethics/11. 정언명령의 보편화 검사와 칸트 윤리의 평가(5주차 온라인).md"}'),i={name:"philosophy/Ethics/11. 정언명령의 보편화 검사와 칸트 윤리의 평가(5주차 온라인).md"};function s(e,t,a,g,_,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<blockquote><p>📎 <strong>슬라이드 위치</strong>: <code>26-2 윤리학 5강.pdf</code> 19~29쪽 (보편법칙의 공식 ~ 자연법칙의 공식 ~ 보편화 검증 ~ 현대적 적용 ~ 철학적 의의 ~ 강점·한계 ~ 최종 요약) — 5-2 온라인 강의(10/2 업로드) 요약 자료 기준</p></blockquote><h2 id="이-노트에-대하여" tabindex="-1">이 노트에 대하여 <a class="header-anchor" href="#이-노트에-대하여" aria-label="Permalink to &quot;이 노트에 대하여&quot;">​</a></h2><p>5주차 오프라인 수업은 『정초』 2절 정독의 앞부분(슬라이드 19~20쪽 도입)에서 끝났다 → <a href="./10. 정언명령, 보편법칙의 정식, 완전·불완전 의무.html">10. 정언명령, 보편법칙의 정식, 완전·불완전 의무</a>. 이어지는 내용(보편화 검사 절차, 현대적 적용, 강점과 한계)은 <strong>5-2 온라인 강의</strong>로 올라왔고, 교수님이 영문·국문 요약을 함께 제공했다. 아래는 그 요약을 <strong>슬라이드 순서대로</strong> 내 말로 다시 정리한 것이다. (원문: <a href="./Raw-Transcripts/2026-10-02_week5-2_online-summary.html">5-2 요약 원문</a>)</p><hr><h2 id="_1-강의의-중심-물음-슬라이드-12·19쪽-흐름" tabindex="-1">1. 강의의 중심 물음 (슬라이드 12·19쪽 흐름) <a class="header-anchor" href="#_1-강의의-중심-물음-슬라이드-12·19쪽-흐름" aria-label="Permalink to &quot;1. 강의의 중심 물음 (슬라이드 12·19쪽 흐름)&quot;">​</a></h2><ul><li>물음: <strong>&quot;선의지를 인도하는 법칙은 무엇인가?&quot;</strong></li><li>칸트의 답: <strong>정언명령</strong> — 개인의 욕망·행복·사회적 이익·외부 권위와 무관하게 적용되는 <strong>무조건적 도덕 원리</strong>. 핵심은 <em>내 행위의 준칙이 모든 이성적 행위자에게 적용되는 보편법칙이 될 수 있는가</em>를 묻는 것.</li></ul><h2 id="_2-보편성의-역사적-의미-슬라이드-15쪽-내용의-확장" tabindex="-1">2. 보편성의 역사적 의미 (슬라이드 15쪽 내용의 확장) <a class="header-anchor" href="#_2-보편성의-역사적-의미-슬라이드-15쪽-내용의-확장" aria-label="Permalink to &quot;2. 보편성의 역사적 의미 (슬라이드 15쪽 내용의 확장)&quot;">​</a></h2><ul><li>위계 사회에서는 신분·부·종교 권위·출생·관습에 따라 사람마다 <strong>다른 특권과 의무</strong>가 인정됐다.</li><li>칸트는 이런 <strong>우연적 조건</strong>을 도덕의 토대로 인정하지 않는다. 진정한 도덕법칙은 &quot;이 규칙은 남에게는 적용되지만 나에게는 아니다&quot;라는 주장을 허용하지 않는다.</li><li>따라서 도덕의 토대가 <strong>신분 → 이성, 특권 → 보편성, 외적 권위 → 자율성</strong>으로 이동한다.</li><li>관련: <a href="./10. 정언명령, 보편법칙의 정식, 완전·불완전 의무.html">10. 정언명령, 보편법칙의 정식, 완전·불완전 의무</a>의 &quot;계몽 이전엔 특권층이 면제됐다&quot; 대목.</li></ul><h2 id="_3-보편법칙의-정식-슬라이드-19쪽" tabindex="-1">3. 보편법칙의 정식 (슬라이드 19쪽) <a class="header-anchor" href="#_3-보편법칙의-정식-슬라이드-19쪽" aria-label="Permalink to &quot;3. 보편법칙의 정식 (슬라이드 19쪽)&quot;">​</a></h2><ul><li>보편화 검사의 질문: <strong>&quot;내가 따르려는 행위 원칙을 모든 사람이 따르는 보편법칙으로 합리적으로 의욕할 수 있는가?&quot;</strong></li><li><strong>준칙(maxim)</strong> = 행위할 때 따르는 <strong>주관적 원칙</strong>. 그래서 칸트 윤리는 &quot;무엇을 했는가&quot;만이 아니라 <strong>&quot;어떤 원칙에 따라 했는가&quot;</strong> 를 평가한다.</li><li>이 검사는 <strong>자기에게만 편한 예외</strong>를 만드는 것을 막는다.</li><li>대표 사례 — <strong>거짓 약속</strong>: 돈이 필요할 때 갚을 생각 없이 갚겠다고 약속하는 준칙을 모두가 따른다면 약속에 대한 신뢰가 사라지고 <strong>약속이라는 제도 자체가 무너진다.</strong> 준칙이 <strong>자기가 기대는 제도를 스스로 파괴</strong>하므로 보편법칙이 될 수 없다.</li></ul><h2 id="_4-자연법칙의-정식-슬라이드-20쪽" tabindex="-1">4. 자연법칙의 정식 (슬라이드 20쪽) <a class="header-anchor" href="#_4-자연법칙의-정식-슬라이드-20쪽" aria-label="Permalink to &quot;4. 자연법칙의 정식 (슬라이드 20쪽)&quot;">​</a></h2><ul><li>표현: <strong>&quot;네 행위의 준칙이 네 의지를 통해 보편적 자연법칙이 되는 것처럼 행위하라.&quot;</strong></li><li>윤리를 물리학으로 환원하려는 게 아니다. 자연법칙은 <strong>무엇이 필연적으로 일어나는지 기술</strong>하고, 도덕법칙은 이성적 존재가 <strong>무엇을 해야 하는지 규정</strong>한다.</li><li>칸트가 자연법칙에서 빌리는 것은 오직 <strong>보편성·일관성·예외 없음</strong>이라는 <em>형식</em>.</li><li>비유: 중력이 부자에게만 예외를 두지 않듯, 도덕법칙도 권력자·부자·<strong>나 자신</strong>에게 편의적 예외를 허용하지 않는다. → 자연법칙 비유는 <strong>도덕적 예외주의와 자기 특권화(self-exemption) 비판</strong>의 장치.</li></ul><h2 id="_5-보편화-검사의-실제-절차-슬라이드-22쪽-완전-불완전-의무-슬라이드-17·21쪽" tabindex="-1">5. 보편화 검사의 실제 절차 (슬라이드 22쪽) + 완전/불완전 의무 (슬라이드 17·21쪽) <a class="header-anchor" href="#_5-보편화-검사의-실제-절차-슬라이드-22쪽-완전-불완전-의무-슬라이드-17·21쪽" aria-label="Permalink to &quot;5. 보편화 검사의 실제 절차 (슬라이드 22쪽) + 완전/불완전 의무 (슬라이드 17·21쪽)&quot;">​</a></h2><p>다섯 단계:</p><ol><li>자신의 <strong>준칙을 명료하게</strong> 규정한다.</li><li>그 준칙을 <strong>모든 사람에게 적용되는 법칙으로 보편화</strong>한다.</li><li>보편화된 준칙이 <strong>자신이 전제하는 제도·관행을 파괴</strong>하는지 묻는다.</li><li><strong>이성적 행위자가 그런 세계를 일관되게 의욕할 수 있는지</strong> 검토한다.</li><li>거기서 생기는 의무가 <strong>완전의무인지 불완전의무인지</strong> 판단한다.</li></ol><ul><li><strong>완전의무</strong>: 엄격하다. 개인의 욕구를 이유로 한 예외를 허용하지 않는다. (거짓말·거짓 약속 금지)</li><li><strong>불완전의무</strong>: 반드시 지켜야 하지만 <strong>이행 방식에 재량(latitude)</strong> 이 있다. (재능 계발, 타인 돕기)</li><li>3단계가 <a href="./10. 정언명령, 보편법칙의 정식, 완전·불완전 의무.html">지난 노트</a>의 <strong>개념상의 모순</strong>, 4단계가 <strong>의지상의 모순</strong>과 연결된다.</li></ul><h2 id="_6-현대적-적용-슬라이드-23쪽" tabindex="-1">6. 현대적 적용 (슬라이드 23쪽) <a class="header-anchor" href="#_6-현대적-적용-슬라이드-23쪽" aria-label="Permalink to &quot;6. 현대적 적용 (슬라이드 23쪽)&quot;">​</a></h2><ul><li><strong>표절·연구 부정</strong>: 모든 연구자가 그렇게 한다면 학문적 신뢰와 저자성 제도가 무너지므로 보편화 불가.</li><li><strong>조작적 알고리즘 설계</strong>: 체류시간·이익을 키우려고 사용자의 <strong>자율적 판단을 우회</strong>하는 설계는 칸트적으로 비판 대상.</li><li><strong>제도적 준칙(institutional maxim)</strong>: 대학·병원·기업·정부도 자기 정책을 지배하는 원칙이 <strong>공개되고 보편화될 수 있는지</strong> 물어야 한다.</li><li><strong>AI 윤리</strong>: 현재의 AI 시스템을 곧바로 <strong>준칙·선의지·도덕법 존중을 가진 도덕적 행위자</strong>로 단정해선 안 된다. 책임의 일차적 대상은 AI를 <strong>설계·배치·이용하고 이익을 얻는</strong> 개발자·기업·규제기관·사용자·제도.</li></ul><h2 id="_7-철학적-의의-슬라이드-24쪽" tabindex="-1">7. 철학적 의의 (슬라이드 24쪽) <a class="header-anchor" href="#_7-철학적-의의-슬라이드-24쪽" aria-label="Permalink to &quot;7. 철학적 의의 (슬라이드 24쪽)&quot;">​</a></h2><ul><li>칸트는 <strong>보편성·이성적 일관성·도덕적 평등·자율성·존엄성</strong>을 하나로 묶었다.</li><li><strong>자유 = 자율</strong>: 원하는 대로 하는 것이 아니라 <strong>이성이 스스로 보편적으로 타당한 법칙을 세우고 그에 따라 행동하는 능력</strong>.</li><li>보편화 검사는 강력한 <strong>도덕적 자기 점검</strong>이다. 남에게는 정직·공정을 요구하면서 나만 슬쩍 예외로 두는 경향을 드러낸다.</li></ul><h2 id="_8-강점과-한계-슬라이드-25-26쪽" tabindex="-1">8. 강점과 한계 (슬라이드 25~26쪽) <a class="header-anchor" href="#_8-강점과-한계-슬라이드-25-26쪽" aria-label="Permalink to &quot;8. 강점과 한계 (슬라이드 25~26쪽)&quot;">​</a></h2><p><strong>강점</strong></p><ul><li>자기중심적 예외, 특권, 기만, 조작, <strong>제도적 위선</strong>을 비판할 수 있다.</li><li>부·권력·지위가 누구도 도덕법 위에 두지 못한다 → 강한 <strong>도덕적 평등</strong> 함의.</li></ul><p><strong>한계</strong></p><ul><li><strong>형식주의</strong>: 준칙을 어떻게 서술하느냐에 따라 검사 결과가 달라질 수 있다.</li><li><strong>맥락·예외 상황</strong>에 둔감하다는 비판.</li><li><strong>감정·돌봄·의존성·구조적 불평등·결과</strong>에 대한 고려 부족. (돌봄윤리: 도덕 행위자는 추상적 입법자가 아니라 <strong>몸을 가진, 취약하고 의존적이며 관계적인 존재</strong>)</li><li>이성적 자율성이 중심이라 <strong>동물·생태계의 직접적 도덕적 지위</strong>를 설명하기 어렵다.</li></ul><h2 id="_9-한-문장-정리-슬라이드-29쪽" tabindex="-1">9. 한 문장 정리 (슬라이드 29쪽) <a class="header-anchor" href="#_9-한-문장-정리-슬라이드-29쪽" aria-label="Permalink to &quot;9. 한 문장 정리 (슬라이드 29쪽)&quot;">​</a></h2><blockquote><p>칸트는 최종 해답이라기보다 <strong>빼놓을 수 없는 대화 상대</strong>다. 그가 던지는 물음: <strong>&quot;내 행위의 원칙을 모든 이성적 행위자를 위한 법칙으로 정당화할 수 있는가, 아니면 나만 슬쩍 예외로 두고 있는가?&quot;</strong></p></blockquote><hr><h2 id="슬라이드-중-요약에-직접-나오지-않은-부분" tabindex="-1">슬라이드 중 요약에 직접 나오지 않은 부분 <a class="header-anchor" href="#슬라이드-중-요약에-직접-나오지-않은-부분" aria-label="Permalink to &quot;슬라이드 중 요약에 직접 나오지 않은 부분&quot;">​</a></h2><ul><li>21쪽: 칸트의 네 가지 예시(자신/타인에 대한 완전·불완전 의무) — 요약은 완전/불완전 구분만 언급.</li><li>27쪽: 칸트와 아리스토텔레스의 상호 교정 — 요약에 없음.</li><li>28쪽: 토론 질문(거짓말은 항상 잘못인가? AI가 의무로부터 행위할 수 있는가? 등)과 다음 주제 <strong>인간성의 정식</strong>(6강 슬라이드 3쪽 복습에 등장).</li></ul><p><em>출처: 5주차 온라인 강의 5-2 요약 자료(윤지영 교수 제공, 영문+국문)를 바탕으로 직접 재구성. 슬라이드 위치는 요약의 주제와 <code>26-2 윤리학 5강.pdf</code> 제목을 대조해 추정한 것.</em></p>',31)])])}const c=l(i,[["render",s]]);export{d as __pageData,c as default};
